def core_token_name(token_id: int) -> str | None:
    return CORE_TOKEN_BY_ID.get(token_id)


def core_token_id(name: str) -> int | None:
    return CORE_TOKEN_ID_BY_NAME.get(name.lower())


def shape_grammar_rule(name: str) -> GrammarRule | None:
    return SHAPE_GRAMMAR_BY_NAME.get(name.lower())
